//! Route-level country rules and the unknown client identity, through the
//! public API, against the reference engine (`check_route_ip_access`,
//! `check_ip_access`). The verdict tables in `tests/data/route_country.json`
//! were generated by running the reference, never written by hand.

use guard_core_engine::geo::{GeoIpHandler, parse_country_lists};
use guard_core_engine::ip_gate::IpGateConfig;
use guard_core_engine::route_config::{RouteConfig, RouteConfigResolver};
use guard_core_rs::geo::{GeoStage, GeoStageConfig};
use rocket::http::Status;
use rocket::local::asynchronous::Client;
use rocket::{get, routes};
use rocket_guard_rs::{BlockGuard, GuardFairing};
use serde_json::Value;
use std::collections::BTreeMap;
use std::net::{IpAddr, SocketAddr};
use std::sync::{Arc, Mutex};

const TABLE: &str = include_str!("data/route_country.json");

struct Countries(BTreeMap<String, String>);

impl GeoIpHandler for Countries {
    fn get_country(&self, ip: IpAddr) -> Option<String> {
        self.0.get(&ip.to_string()).cloned()
    }
}

struct Table {
    json: Value,
}

impl Table {
    fn new() -> Self {
        Self {
            json: serde_json::from_str(TABLE).expect("fixture"),
        }
    }

    fn lists(&self, key: &str) -> Vec<Vec<String>> {
        self.json[key]
            .as_array()
            .expect(key)
            .iter()
            .map(|list| {
                list.as_array()
                    .expect("list")
                    .iter()
                    .map(|v| v.as_str().expect("entry").to_owned())
                    .collect()
            })
            .collect()
    }

    fn ips(&self) -> Vec<String> {
        self.json["ips"]
            .as_array()
            .expect("ips")
            .iter()
            .map(|v| v.as_str().expect("ip").to_owned())
            .collect()
    }

    fn handler(&self) -> Arc<dyn GeoIpHandler> {
        let map = self.json["countries"]
            .as_object()
            .expect("countries")
            .iter()
            .filter_map(|(ip, country)| Some((ip.clone(), country.as_str()?.to_owned())))
            .collect();
        Arc::new(Countries(map))
    }

    fn verdicts(&self, key: &str) -> Vec<char> {
        self.json[key].as_str().expect(key).chars().collect()
    }
}

fn route_of(
    whitelist: &[String],
    blacklist: &[String],
    blocked: &[String],
    countries: &[String],
) -> RouteConfig {
    let some = |list: &[String]| (!list.is_empty()).then(|| list.to_vec());
    RouteConfig {
        ip_whitelist: some(whitelist),
        ip_blacklist: some(blacklist),
        blocked_countries: some(blocked),
        whitelist_countries: some(countries),
        ..RouteConfig::default()
    }
}

fn stage_for(table: &Table, countries: &[String]) -> GeoStage {
    GeoStage::builder(GeoStageConfig {
        gate: parse_country_lists(countries, [] as [&str; 0]),
        handler: Some(table.handler()),
        passive_mode: false,
    })
    .build()
}

fn gate_for(whitelist: &[String]) -> IpGateConfig {
    IpGateConfig::new(whitelist, [] as [&str; 0], [] as [&str; 0]).expect("lists")
}

fn expected(verdict: char) -> bool {
    verdict != 'F'
}

fn report(kind: &str, rows: usize, total: usize, failures: &[String]) {
    assert_eq!(rows, total);
    assert!(
        failures.is_empty(),
        "{} of {rows} {kind} rows differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[tokio::test]
async fn route_verdicts_match_the_reference() {
    let table = Table::new();
    let (lists, blocked, countries) = (
        table.lists("route_lists"),
        table.lists("blocked_countries"),
        table.lists("whitelist_countries"),
    );
    let verdicts = table.verdicts("route");
    let harness = Harness::new(&table, &[], &[]).await;
    let (mut row, mut failures) = (0, Vec::new());
    for rwl in &lists {
        for rbl in &lists {
            for bc in &blocked {
                for wc in &countries {
                    for ip in table.ips() {
                        let route = route_of(rwl, rbl, bc, wc);
                        let allowed = harness.allowed(&ip, &route).await;
                        if allowed != expected(verdicts[row]) {
                            failures.push(format!(
                                "rwl={rwl:?} rbl={rbl:?} bc={bc:?} wc={wc:?} ip={ip}: allowed={allowed} want={}",
                                expected(verdicts[row])
                            ));
                        }
                        row += 1;
                    }
                }
            }
        }
    }
    report("route", row, verdicts.len(), &failures);
}

#[tokio::test]
async fn global_verdicts_match_the_reference() {
    let table = Table::new();
    let (lists, countries) = (
        table.lists("global_lists"),
        table.lists("global_whitelist_countries"),
    );
    let verdicts = table.verdicts("global");
    let (mut row, mut failures) = (0, Vec::new());
    for wl in &lists {
        for wc in &countries {
            let harness = Harness::new(&table, wl, wc).await;
            for ip in table.ips() {
                let allowed = harness.allowed(&ip, &RouteConfig::default()).await;
                if allowed != expected(verdicts[row]) {
                    failures.push(format!(
                        "wl={wl:?} wc={wc:?} ip={ip}: allowed={allowed} want={}",
                        expected(verdicts[row])
                    ));
                }
                row += 1;
            }
        }
    }
    report("global", row, verdicts.len(), &failures);
}

#[tokio::test]
async fn route_and_global_rules_compose_like_the_reference() {
    let table = Table::new();
    let (lists, blocked, countries, glists, gcountries) = (
        table.lists("route_lists"),
        table.lists("blocked_countries"),
        table.lists("whitelist_countries"),
        table.lists("global_lists"),
        table.lists("global_whitelist_countries"),
    );
    let verdicts = table.verdicts("combined");
    let (mut row, mut failures) = (0, Vec::new());
    for rwl in &lists {
        for bc in &blocked {
            for wc in &countries {
                for gwl in &glists {
                    for gwc in &gcountries {
                        let harness = Harness::new(&table, gwl, gwc).await;
                        let route = route_of(rwl, &[], bc, wc);
                        for ip in table.ips() {
                            let allowed = harness.allowed(&ip, &route).await;
                            if allowed != expected(verdicts[row]) {
                                failures.push(format!(
                                    "route(wl={rwl:?} bc={bc:?} wc={wc:?}) global(wl={gwl:?} wc={gwc:?}) ip={ip}: allowed={allowed} want={}",
                                    expected(verdicts[row])
                                ));
                            }
                            row += 1;
                        }
                    }
                }
            }
        }
    }
    report("combined", row, verdicts.len(), &failures);
}

#[get("/api")]
fn api(_guard: BlockGuard) -> &'static str {
    "ok"
}

/// One global configuration; the route under test is swapped per request.
struct Harness {
    client: Client,
    route: Arc<Mutex<Option<Arc<RouteConfig>>>>,
}

impl Harness {
    async fn new(table: &Table, whitelist: &[String], countries: &[String]) -> Self {
        let route: Arc<Mutex<Option<Arc<RouteConfig>>>> = Arc::new(Mutex::new(None));
        let cell = route.clone();
        let resolver: RouteConfigResolver =
            Arc::new(move |_method, _path| cell.lock().expect("route").clone());
        let mut fairing = GuardFairing::with_defaults()
            .with_geo_handler(table.handler())
            .with_route_configs(resolver);
        if !whitelist.is_empty() {
            fairing = fairing.with_ip_gate(gate_for(whitelist));
        }
        if !countries.is_empty() {
            fairing = fairing.with_geo_blocking(stage_for(table, countries));
        }
        let client = Client::tracked(rocket::build().attach(fairing).mount("/", routes![api]))
            .await
            .expect("valid rocket");
        Self { client, route }
    }

    async fn allowed(&self, ip: &str, route: &RouteConfig) -> bool {
        *self.route.lock().expect("route") = Some(Arc::new(route.clone()));
        let mut request = self.client.get("/api");
        if ip != "unknown" {
            request = request.remote(SocketAddr::new(ip.parse::<IpAddr>().expect("ip"), 45_000));
        }
        request.dispatch().await.status() == Status::Ok
    }
}
